import json
import pandas as pd


def norm_status(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return "active" if v else "inactive"
    s = str(v).strip()
    if s.lower() in ("true", "false"):
        return "active" if s.lower() == "true" else "inactive"
    return s


def norm_date(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    return pd.to_datetime(v).strftime("%Y-%m-%d")


ID_KEYS = ("user_id", "id", "userId")
EMAIL_KEYS = ("email", "email_address")
NAME_KEYS = ("full_name", "name", "userName")
DATE_KEYS = ("registration_date", "created_at", "joined")
STATUS_KEYS = ("status", "is_active", "active")


def pick(row, keys):
    for k in keys:
        if k in row and row[k] is not None and not (isinstance(row[k], float) and pd.isna(row[k])):
            return row[k]
    return None


def unify(row):
    return {
        "user_id": int(pick(row, ID_KEYS)),
        "name": pick(row, NAME_KEYS),
        "email": pick(row, EMAIL_KEYS),
        "created_date": norm_date(pick(row, DATE_KEYS)),
        "status": norm_status(pick(row, STATUS_KEYS)),
    }


a = [unify(r) for r in json.load(open("/data/source_a/users.json"))]
b = [unify(r) for r in pd.read_csv("/data/source_b/users.csv").to_dict("records")]
c = [unify(r) for r in pd.read_parquet("/data/source_c/users.parquet").to_dict("records")]

sources = {"source_a": a, "source_b": b, "source_c": c}
PRIORITY = ["source_a", "source_b", "source_c"]
FIELDS = ["name", "email", "created_date", "status"]

# index by user_id per source
per_source = {s: {rec["user_id"]: rec for rec in recs} for s, recs in sources.items()}
all_ids = sorted({uid for idx in per_source.values() for uid in idx})

merged = []
conflicts = []
for uid in all_ids:
    present = [s for s in PRIORITY if uid in per_source[s]]
    out = {"user_id": uid}
    for field in FIELDS:
        vals = {s: per_source[s][uid].get(field) for s in present}
        non_null = {s: v for s, v in vals.items() if v is not None}
        selected = None
        for s in PRIORITY:
            if s in non_null:
                selected = non_null[s]
                break
        out[field] = selected
        distinct = set(non_null.values())
        if len(distinct) > 1:
            conflicts.append({
                "user_id": uid,
                "field": field,
                "values": {s: vals[s] for s in present if vals[s] is not None},
                "selected": selected,
            })
    merged.append(out)

df = pd.DataFrame(merged, columns=["user_id", "name", "email", "created_date", "status"])
df["user_id"] = df["user_id"].astype("int64")
for col in ["name", "email", "created_date", "status"]:
    df[col] = df[col].astype("object")
df.to_parquet("/app/merged_users.parquet", index=False)

report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
json.dump(report, open("/app/conflicts.json", "w"), indent=2, default=str)
print(df)
print("conflicts:", len(conflicts))

